import 'reflect-metadata';
import type { IncomingMessage, ServerResponse } from 'node:http';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { NestFactory } from '@nestjs/core';
import { SwaggerModule } from '@nestjs/swagger';
import { AppModule } from './app.module.js';
import { configureApp } from './app.setup.js';
import metadata from './metadata.js';

async function createApp() {
  // DTO schemas for /api/docs, generated by `pnpm swagger:metadata`. Vercel compiles this file
  // without the Nest CLI plugin, so the docs must not depend on it.
  await SwaggerModule.loadPluginMetadata(metadata);
  return configureApp(await NestFactory.create(AppModule));
}

type RequestListener = (req: IncomingMessage, res: ServerResponse) => void;
let listener: Promise<RequestListener> | undefined;

/**
 * Vercel entry. Vercel imports this module and calls the default export per request. It must not
 * wait on app.listen(): Vercel's launcher swaps http.Server#listen for a stub that never calls back,
 * so awaiting it hung every request. The Nest app is created once per instance and reused.
 */
export default async function handler(req: IncomingMessage, res: ServerResponse) {
  listener ??= createApp()
    .then(async (app) => {
      await app.init();
      return app.getHttpAdapter().getInstance() as RequestListener;
    })
    .catch((e: unknown) => {
      listener = undefined; // let the next request retry a failed boot
      throw e;
    });
  (await listener)(req, res);
}

// Run directly (`nest start`, `node dist/main.js`, `vercel dev` devCommand): serve on a port.
// PORT is set by hosts such as `vercel dev`; API_PORT by our .env for `pnpm dev`.
const entry = process.argv[1] ? resolve(process.argv[1]) : '';
const self = fileURLToPath(import.meta.url);
if (entry === self || `${entry}.js` === self) {
  const app = await createApp();
  await app.listen(process.env.PORT ?? process.env.API_PORT ?? 4000);
}
